function openDoc(type) {
  $("doc-t").textContent = type === "privacy" ? "Privacy Policy" : "Terms of Service";
  $("doc-b").innerHTML = type === "privacy"
    ? "<p>All settings, account preferences, and notes are stored locally in your browser via localStorage. No personal account credentials are sent to external servers.</p>"
